/* glyph index of a character: lower case folds to upper case when the font
 * has none, anything missing (and C1 controls) draws as '?' */
static uint32_t glyph(const felucca_font_t *f, uint32_t ch)
{
    if (ch >= 'a' && ch <= 'z' && f->last < 'a')
        ch -= 32u;
    if (ch < f->first || ch > f->last || (ch >= 127u && ch < 160u))
        ch = '?';
    return ch - f->first;
}

static float fexp2(float x)
{
    int i = (int)(x < 0 ? x - 1.0f : x);
    float f = x - (float)i, r = 1.0f;
    float p = 1.0f + f * (0.6931472f + f * (0.2402265f + f * (0.0555041f + f * 0.0096181f)));
    if (i > 0)
        while (i--)
            r *= 2.0f;
    else
        while (i++)
            r *= 0.5f;
    return p * r;
}

/* app.c app_sysex: a SysEx frame from USB (the bytes between F0 and F7); 1 = ours, taken */
int bs_usb_sysex(const uint8_t *p, uint32_t n)
{
    uint8_t m[6];
    if (n < 4u || p[0] != 0x7Du || p[1] != 'F' || p[2] != 'S')
        return 0;
    if (n > 4u) {                                /* Big Knobs, MASTER, a press */
        bs_panel_in(p, n);
        return 1;
    }
    m[0] = 0xF0; m[1] = 0x7D; m[2] = 'F'; m[3] = 'S'; m[4] = p[3]; m[5] = 0xF7;
    sm_sysex(m, 6);                              /* (a new viewer, or 01: sm_take_full_request, the whole screen) */
    return 1;
}

/* a polygon (points in pixels, the PIL convention: pixel centres at .5) into the mask, 4 x 4 samples a pixel,
 * even-odd; the mask keeps the larger coverage */
static void mask_poly(const float *p, int n)
{
    float minx = p[0], maxx = p[0], miny = p[1], maxy = p[1];
    int i, x0, x1, y0, y1, y;
    static uint8_t cnt[SW];
    for (i = 1; i < n; i++) {
        minx = p[2 * i] < minx ? p[2 * i] : minx;
        maxx = p[2 * i] > maxx ? p[2 * i] : maxx;
        miny = p[2 * i + 1] < miny ? p[2 * i + 1] : miny;
        maxy = p[2 * i + 1] > maxy ? p[2 * i + 1] : maxy;
    }
    x0 = (int)minx - 1;
    x1 = (int)maxx + 2;
    y0 = (int)miny - 1;
    y1 = (int)maxy + 2;
    x0 = x0 < mbox.x0 ? mbox.x0 : x0;
    x1 = x1 > mbox.x1 ? mbox.x1 : x1;
    y0 = y0 < mbox.y0 ? mbox.y0 : y0;
    y1 = y1 > mbox.y1 ? mbox.y1 : y1;
    if (x1 <= x0 || y1 <= y0)
        return;
    for (y = y0; y < y1; y++) {
        int s, x;
        memset(cnt + x0, 0, (uint32_t)(x1 - x0));
        for (s = 0; s < 4; s++) {
            float sy = (float)y + s * 0.25f, xs[64];   /* the samples of PIL's 4x raster: x + c / 4, y + s / 4 */
            int nx = 0, j;
            for (i = 0; i < n; i++) {
                float ax = p[2 * i], ay = p[2 * i + 1], bx = p[2 * ((i + 1) % n)], by = p[2 * ((i + 1) % n) + 1];
                if ((ay <= sy && by > sy) || (by <= sy && ay > sy)) {
                    if (nx < 64)
                        xs[nx++] = ax + (sy - ay) * (bx - ax) / (by - ay);
                }
            }
            for (i = 1; i < nx; i++) {                /* sort the crossings */
                float v = xs[i];
                for (j = i - 1; j >= 0 && xs[j] > v; j--)
                    xs[j + 1] = xs[j];
                xs[j + 1] = v;
            }
            for (i = 0; i + 1 < nx; i += 2) {         /* the spans: count the sample columns inside */
                float a = xs[i], b = xs[i + 1];
                int c0 = iceil(a * 4.0f), c1 = iceil(b * 4.0f);   /* the sample columns in [a, b) */
                int c;
                if (c0 < x0 * 4)
                    c0 = x0 * 4;
                if (c1 > x1 * 4)
                    c1 = x1 * 4;
                for (c = c0; c < c1; c++)
                    cnt[c >> 2]++;
            }
        }
        for (x = x0; x < x1; x++) {
            uint32_t v = (uint32_t)(cnt[x] > 16 ? 16 : cnt[x]) * 255u / 16u;
            uint8_t *m = MASK + y * SW + x;
            if (v > *m)
                *m = (uint8_t)v;
        }
    }
}

static void tabs(const char *const *names, int n, int cur, int y)
{
    float ws[4], sum = 0, gap, x;
    int i;
    for (i = 0; i < n; i++) {
        ws[i] = twidth(&F_HEAD9, names[i], 0.6f);
        sum += ws[i];
    }
    gap = (216 - sum) / (n + 1);
    x = 12 + gap;
    for (i = 0; i < n; i++) {
        text(x, (float)y, &F_HEAD9, names[i], i == cur ? IVORY : GREY, 0.6f, 'l', 1.0f);
        if (i == cur)
            lozenge((float)(int)(x + ws[i] / 2 + 0.5f), (float)(y + 14), 2.0f, GOLD, 1.0f, 0);
        x += ws[i] + gap;
    }
}

static void header_text(const char *left, const char *right)
{
    text(12, HEAD_Y, &F_HEAD12, left, IVORY, 1.5f, 'l', 1.0f);
    if (right)
        text(228, HEAD_Y, &F_HEAD12, right, IVORY, 1.5f, 'r', 1.0f);
}

static void ota_unstage(void)
{
    uint32_t i;
    for (i = 0; i < OTA_AREA_LEN; i += 0x1000u)
        ota_erase(OTA_AREA + i);
}

static void stream_start(stream *s, const erk_smp *m, int32_t w)
{
    s->base = bk->data + m->off;
    s->loop = m->loop;
    s->loop_len = m->loop_len;
    s->lend = m->loop_len ? m->loop + m->loop_len : m->len;
    s->h1 = m->h1;
    s->h2 = m->h2;
    s->pos = 0;
    s->done = 0;
    erk_dec_start(&s->d, s->base, 0, 0);
    s->xm1 = 0;
    s->x0 = dec_one(s);
    s->x1 = dec_one(s);
    s->x2 = dec_one(s);
    s->frac = 0;
    s->w = s->wt = w;
}

void erk_note_on(int key, int vel)
{
    const erk_key *k;
    const erk_vel *e;
    const erk_smp *s0, *s1;
    voice *v;
    int i, n = 0, nl;
    int32_t g, a;
    key -= ERK_KEY0;
    if (key < 0 || key >= ERK_KEYS || vel <= 0 || !bk)
        return;
    if (vel > 127)
        vel = 127;
    pad_on(key, vel);
    if (soft)                                         /* una corda: the hammer meets fewer strings */
        vel = 1 + (vel * (32767 - ((st.una * 6553) >> 15))) / 32768;
    k = &bk->key[key];
    e = &bk->vel[vel];
    nl = bk->hdr->nlayers;
    for (i = 0; i < ERK_VOICES + ERK_DYING; i++) {
        voice *o = &vc[i];
        if (o->state == V_FREE)
            continue;
        if (o->key == key && o->state != V_FADE) {    /* the same string struck again */
            o->state = V_FADE;
            o->m = FADE_M;
        }
        if (o->state != V_FADE)
            n++;
    }
    if (n >= ERK_VOICES) {                            /* steal: the quietest, released ones first */
        voice *q = 0;
        int32_t qg = 0x7fffffff;
        for (i = 0; i < ERK_VOICES + ERK_DYING; i++) {
            voice *o = &vc[i];
            int32_t gg;
            if (o->state == V_FREE || o->state == V_FADE)
                continue;
            gg = gain_of(o) >> (o->state == V_ON ? 0 : 2);
            if (gg < qg) {
                qg = gg;
                q = o;
            }
        }
        if (q) {
            q->state = V_FADE;
            q->m = FADE_M;
        }
    }
    v = alloc(0, ERK_VOICES + ERK_DYING);
    if (!v) {                                         /* every slot fading: cut the quietest */
        v = &vc[0];
        for (i = 1; i < ERK_VOICES + ERK_DYING; i++)
            if (gain_of(&vc[i]) < gain_of(v))
                v = &vc[i];
    }
    memset(v, 0, sizeof *v);
    v->key = (uint8_t)key;
    v->flags = (uint8_t)(k->flags | (key_sost(key) ? F_SOST : 0));
    v->rel = k->rel;
    v->inc = k->inc;
    if (st.detune) {                                  /* vintage: the unisons a little apart, by key */
        int32_t c = (int32_t)(((uint32_t)key * 2654435761u) >> 24) - 128;   /* -128..127 */
        v->inc = (uint32_t)((int32_t)v->inc + ((((int32_t)v->inc >> 4) * c * st.detune) >> 17));   /* +-detune/10 cents */
    }
    s0 = &bk->smp[k->zone * nl + e->l0];
    s1 = &bk->smp[k->zone * nl + e->l1];
    {   /* the CPU: at most ERK_XF_MAX notes crossfade two layers at once; the next ones take the nearer layer */
        int x = 0;
        for (i = 0; i < ERK_VOICES + ERK_DYING; i++)
            x += vc[i].state != V_FREE && vc[i].nst == 2;
        if (e->w && e->l1 != e->l0 && x >= ERK_XF_MAX) {
            if (e->w >= 16384)
                s0 = s1;
            s1 = s0;
        }
    }
    if (e->w && e->l1 != e->l0 && s0 != s1) {
        v->nst = 2;
        stream_start(&v->st[0], s0, ((32767 - e->w) * (int32_t)s0->gain) >> 12);
        stream_start(&v->st[1], s1, (e->w * (int32_t)s1->gain) >> 12);
        v->keep = e->w >= 16384;
        v->wend = clampi((int32_t)(v->keep ? s1->gain : s0->gain) << 3, 0, 32767);
    } else {
        v->nst = 1;
        stream_start(&v->st[0], s0, (int32_t)s0->gain << 3);    /* Q12 -> Q15 */
    }
    for (i = 0; i < v->nst; i++)
        v->st[i].w = v->st[i].wt = clampi(v->st[i].w, 0, 32767);
    v->w0s = v->st[0].w;
    v->w1s = v->st[1].w;
    g = e->amp;
    if (soft)
        g = (g * (32767 - ((st.una * 9000) >> 15))) >> 15;
    v->amp = g;
    v->env = 1u << 30;
    v->m = k->m1;
    v->m2 = k->m2;
    v->mr1 = k->mr1;
    v->mr2 = k->mr2;
    v->knee = k->knee;
    a = clampi((e->a * st.bscale) >> 12, 200, 16384);
    if (soft)
        a = (a * (32767 - ((st.una * 12000) >> 15))) >> 15;
    a = a > k->a_floor ? a : k->a_floor;
    v->a = a << 8;
    v->a_floor = (k->a_floor < a ? k->a_floor : a) << 8;
    v->dark = k->dark;
    pan_of(key, &v->pl, &v->pr);
#if ERK_MODAL
    if (cfg.mode != ERK_SAMPLED && cfg.modal) {       /* the partials carry the decay */
        erkm_start(&v->mv, cfg.modal, key, e->l0, e->l1, e->w, vel, soft);
        v->senv = 1u << 30;
        v->m = v->m2 = 1u << 30;
        v->dark = 65535;
        if (cfg.mode == ERK_MODELLED) {
            v->nst = 0;
            v->a = v->a_floor = 16384 << 8;
        }
    }
#endif
    v->gl = gain_of(v) * v->pl;                       /* start at the target: keep the hammer transient */
    v->gr = gain_of(v) * v->pr;
    v->state = V_ON;
}
